use crate::connection_geometry::{ConnectionRegion,WorldConnectionPoint};
use crate::physical_geometry::PhysicalGeometry;
use crate::resources::{BaseResource,ConnectionPoint,ConnectionSites,Material};
use serde::{Deserialize,Deserializer,Serialize};
use std::collections::HashSet;
#[derive(Serialize,Deserialize,Clone,Copy,Debug,PartialEq)]pub struct Placement{pub x:f64,pub y:f64,pub rotation_radians:f64}
#[derive(Serialize,Deserialize,Clone,Copy,Debug,PartialEq,Eq,Hash,Default)]pub struct PhysicalConstituentId(pub u64);
#[derive(Serialize,Clone,Debug,PartialEq)]pub struct StructuralUnit{pub physical_id:PhysicalConstituentId,pub material:Material,pub placement:Placement,#[serde(default,skip_serializing_if="Option::is_none")]pub geometry:Option<PhysicalGeometry>}
impl StructuralUnit{pub fn new(resource_name:impl Into<String>,placement:Placement)->Self{Self{physical_id:PhysicalConstituentId(0),material:Material::free_base(resource_name,1.0),placement,geometry:None}}pub fn from_material(material:Material,placement:Placement)->Option<Self>{if !material.is_valid()||material.is_empty(){return None}Some(Self{physical_id:PhysicalConstituentId(0),material,placement,geometry:None})}pub fn resource_name(&self)->Option<&str>{let[(name,amount)]=self.material.parts.as_slice()else{return None};if self.material.internal_bonds.is_empty()&&(*amount-1.0).abs()<=f64::EPSILON{Some(name.as_str())}else{None}}pub fn properties(&self,catalog:&[BaseResource])->Option<crate::resources::ResourceProperties>{if !self.material.is_valid()||!self.material.parts.iter().all(|(name,_)|catalog.iter().any(|base|base.name==*name)){return None}Some(self.material.weighted_properties(catalog))}fn external_geometry_resource<'a>(&self,catalog:&'a[BaseResource])->Option<&'a BaseResource>{if self.material.has_internal_structure(){return None}let(name,amount)=self.material.parts.first()?;if(*amount-1.0).abs()>f64::EPSILON{return None}catalog.iter().find(|base|base.name==*name)}pub fn connection_sites(&self,catalog:&[BaseResource])->Option<ConnectionSites>{if let Some(geometry)=&self.geometry{return Some(geometry.shape().connection_sites())}if !self.material.has_internal_structure(){let[(name,amount)]=self.material.parts.as_slice()else{return None};if(*amount-1.0).abs()>f64::EPSILON{return None}return catalog.iter().find(|base|base.name==*name).map(|base|base.shape.connection_sites())}self.external_geometry_resource(catalog).map(|base|base.shape.connection_sites())}pub fn shape<'a>(&'a self,catalog:&'a[BaseResource])->Option<&'a crate::resources::Shape>{if let Some(geometry)=&self.geometry{return Some(geometry.shape())}if !self.material.has_internal_structure(){let[(name,amount)]=self.material.parts.as_slice()else{return None};if(*amount-1.0).abs()>f64::EPSILON{return None}return catalog.iter().find(|base|base.name==*name).map(|base|&base.shape)}self.external_geometry_resource(catalog).map(|base|&base.shape)}pub fn replace_geometry(&mut self,shape:crate::resources::Shape)->bool{if !shape.is_valid(){return false}match &mut self.geometry{Some(geometry)=>geometry.replace(shape),None=>{self.geometry=Some(PhysicalGeometry::from_default(&shape));true}}}pub fn realize_default_geometry(&mut self,catalog:&[BaseResource])->bool{if self.geometry.is_some(){return true}let Some(shape)=self.shape(catalog).cloned()else{return false};self.geometry=Some(PhysicalGeometry::from_default(&shape));true}}
impl<'de>Deserialize<'de>for StructuralUnit{fn deserialize<D>(deserializer:D)->Result<Self,D::Error>where D:serde::Deserializer<'de>{#[derive(Deserialize)]struct LegacyStructuralMaterial{material:Material}#[derive(Deserialize)]#[serde(untagged)]enum StoredMaterial{Direct(Material),Wrapped(LegacyStructuralMaterial)}#[derive(Deserialize)]struct Stored{#[serde(default)]physical_id:PhysicalConstituentId,material:Option<StoredMaterial>,resource_name:Option<String>,placement:Placement,#[serde(default)]geometry:Option<PhysicalGeometry>}let s=Stored::deserialize(deserializer)?;let m=match s.material{Some(StoredMaterial::Direct(m))=>m,Some(StoredMaterial::Wrapped(w))=>w.material,None=>Material::free_base(s.resource_name.ok_or_else(||serde::de::Error::custom("structural unit has no material"))?,1.0)};if !m.is_valid()||m.is_empty(){return Err(serde::de::Error::custom("invalid material"))}Ok(Self{physical_id:s.physical_id,material:m,placement:s.placement,geometry:s.geometry})}}
#[derive(Serialize,Deserialize,Clone,Copy,Debug,PartialEq,Eq,Hash)]pub struct ConnectionSiteRef{pub unit_index:usize,pub point_index:usize}
#[derive(Serialize,Deserialize,Clone,Copy,Debug,PartialEq)]pub enum ConnectionEndpoint{Corner{point_index:usize},LineEndpoint{point_index:usize},Boundary{angle_radians:f64},Fluid{x:f64,y:f64}}
#[derive(Serialize,Clone,Copy,Debug,PartialEq)]pub struct BondEndpoint{pub constituent_id:PhysicalConstituentId,pub location:ConnectionEndpoint}
impl BondEndpoint{pub fn new(constituent_id:PhysicalConstituentId,location:ConnectionEndpoint)->Self{Self{constituent_id,location}}}
impl<'de>Deserialize<'de>for BondEndpoint{fn deserialize<D>(deserializer:D)->Result<Self,D::Error>where D:Deserializer<'de>{#[derive(Deserialize)]struct Stored{constituent_id:Option<PhysicalConstituentId>,unit_index:Option<usize>,location:ConnectionEndpoint}let s=Stored::deserialize(deserializer)?;let id=s.constituent_id.unwrap_or_else(||PhysicalConstituentId(s.unit_index.map(|i|u64::MAX-i as u64).unwrap_or(0)));Ok(Self{constituent_id:id,location:s.location})}}
impl ConnectionEndpoint{pub fn region(self,unit:&StructuralUnit,catalog:&[BaseResource])->Option<ConnectionRegion>{match self{Self::Corner{point_index}=>match unit.connection_sites(catalog)?{ConnectionSites::Corners(points)=>points.get(point_index).copied().map(|p|ConnectionRegion::Corner(crate::connection_geometry::transform_connection_point(p,unit.placement.x,unit.placement.y,unit.placement.rotation_radians))),_=>None},Self::LineEndpoint{point_index}=>match unit.connection_sites(catalog)?{ConnectionSites::Endpoints(points)=>points.get(point_index).copied().map(|p|ConnectionRegion::Corner(crate::connection_geometry::transform_connection_point(p,unit.placement.x,unit.placement.y,unit.placement.rotation_radians))),_=>None},Self::Boundary{..}=>match unit.connection_sites(catalog)?{ConnectionSites::Circumference{radius}=>Some(ConnectionRegion::Boundary{center_x:unit.placement.x,center_y:unit.placement.y,radius}),_=>None},Self::Fluid{..}=>match unit.connection_sites(catalog)?{ConnectionSites::Undetermined=>{let radius=unit.shape(catalog)?.form.bounding_radius();Some(ConnectionRegion::Fluid{center_x:unit.placement.x,center_y:unit.placement.y,effective_radius:radius})}_=>None}}}pub fn world_point(self,unit:&StructuralUnit,catalog:&[BaseResource])->Option<WorldConnectionPoint>{let(local_x,local_y,normal_x,normal_y)=match self{Self::Corner{point_index}=>{let ConnectionSites::Corners(points)=unit.connection_sites(catalog)? else{return None};let p=*points.get(point_index)?;(p.x,p.y,p.direction_radians.cos(),p.direction_radians.sin())},Self::LineEndpoint{point_index}=>{let ConnectionSites::Endpoints(points)=unit.connection_sites(catalog)? else{return None};let p=*points.get(point_index)?;(p.x,p.y,p.direction_radians.cos(),p.direction_radians.sin())},Self::Boundary{angle_radians}=>{let ConnectionSites::Circumference{radius}=unit.connection_sites(catalog)? else{return None};let(nx,ny)=(angle_radians.cos(),angle_radians.sin());(radius*nx,radius*ny,nx,ny)},Self::Fluid{x,y}=>(x,y,0.0,0.0)};let(s,c)=unit.placement.rotation_radians.sin_cos();Some(WorldConnectionPoint{x:unit.placement.x+local_x*c-local_y*s,y:unit.placement.y+local_x*s+local_y*c,normal_x:normal_x*c-normal_y*s,normal_y:normal_x*s+normal_y*c})}pub fn same_location(self,other:Self)->bool{match(self,other){(Self::Corner{point_index:a},Self::Corner{point_index:b})=>a==b,(Self::LineEndpoint{point_index:a},Self::LineEndpoint{point_index:b})=>a==b,(Self::Boundary{angle_radians:a},Self::Boundary{angle_radians:b})=>(a-b).abs()<=1e-12,(Self::Fluid{x:ax,y:ay},Self::Fluid{x:bx,y:by})=>(ax-bx).hypot(ay-by)<=1e-12,_=>false}}}
#[derive(Serialize,Deserialize,Clone,Copy,Debug,PartialEq)]pub struct Bond{pub endpoint_a:BondEndpoint,pub endpoint_b:BondEndpoint,pub strength:f64,#[serde(default)]pub bond_energy:f64}
impl Bond{pub fn touches(&self,u:PhysicalConstituentId,location:ConnectionEndpoint)->bool{(self.endpoint_a.constituent_id==u&&self.endpoint_a.location.same_location(location))||(self.endpoint_b.constituent_id==u&&self.endpoint_b.location.same_location(location))}pub fn has_same_identity(&self,o:&Bond)->bool{(self.endpoint_a.constituent_id==o.endpoint_a.constituent_id&&self.endpoint_a.location.same_location(o.endpoint_a.location)&&self.endpoint_b.constituent_id==o.endpoint_b.constituent_id&&self.endpoint_b.location.same_location(o.endpoint_b.location))||(self.endpoint_a.constituent_id==o.endpoint_b.constituent_id&&self.endpoint_a.location.same_location(o.endpoint_b.location)&&self.endpoint_b.constituent_id==o.endpoint_a.constituent_id&&self.endpoint_b.location.same_location(o.endpoint_a.location))}pub fn is_valid(&self,connection_is_valid:impl Fn(BondEndpoint)->bool)->bool{self.endpoint_a.constituent_id.0!=0&&self.endpoint_b.constituent_id.0!=0&&self.endpoint_a.constituent_id!=self.endpoint_b.constituent_id&&self.bond_energy.is_finite()&&self.bond_energy>=0.0&&connection_is_valid(self.endpoint_a)&&connection_is_valid(self.endpoint_b)}}
fn units_strictly_overlap(a:&StructuralUnit,b:&StructuralUnit,catalog:&[BaseResource])->bool{let(Some(form_a),Some(form_b))=(a.shape(catalog),b.shape(catalog))else{return false};let pa=crate::material_geometry::PlacedMaterialPart{part_index:0,form:form_a.form.clone(),placement:a.placement};let pb=crate::material_geometry::PlacedMaterialPart{part_index:1,form:form_b.form.clone(),placement:b.placement};if !crate::material_geometry::placed_forms_overlap(&pa,&pb,0.0){return false}let dx=b.placement.x-a.placement.x;let dy=b.placement.y-a.placement.y;let distance=dx.hypot(dy);let(sx,sy)=if distance>1e-12{(dx/distance,dy/distance)}else{(1.0,0.0)};let scale=pa.form.bounding_radius().max(pb.form.bounding_radius()).max(1.0);let epsilon=1e-8*scale;let shifted=crate::material_geometry::PlacedMaterialPart{part_index:0,form:pa.form.clone(),placement:Placement{x:a.placement.x-sx*epsilon,y:a.placement.y-sy*epsilon,rotation_radians:a.placement.rotation_radians}};crate::material_geometry::placed_forms_overlap(&shifted,&pb,0.0)}
#[derive(Serialize,Clone,Debug)]pub struct PhysicalConstituentGraph{pub units:Vec<StructuralUnit>,pub bonds:Vec<Bond>,#[serde(default)]next_constituent_id:u64}
impl<'de>Deserialize<'de>for PhysicalConstituentGraph{fn deserialize<D>(deserializer:D)->Result<Self,D::Error>where D:Deserializer<'de>{#[derive(Deserialize)]struct Stored{units:Vec<StructuralUnit>,bonds:Vec<Bond>,#[serde(default)]next_constituent_id:u64}let mut s=Stored::deserialize(deserializer)?;let mut used=HashSet::new();let mut next=s.next_constituent_id.max(1);for unit in &mut s.units{let id=unit.physical_id;if id.0==0||used.contains(&id){while next==0||used.contains(&PhysicalConstituentId(next)){next=next.checked_add(1).ok_or_else(||serde::de::Error::custom("physical constituent ID space exhausted"))?}unit.physical_id=PhysicalConstituentId(next);used.insert(unit.physical_id);next=next.saturating_add(1)}else{used.insert(id);}}if let Some(max_id)=used.iter().map(|id|id.0).max(){next=next.max(max_id.saturating_add(1)).max(1)}for bond in &mut s.bonds{for endpoint in [&mut bond.endpoint_a,&mut bond.endpoint_b]{if endpoint.constituent_id.0>=u64::MAX.saturating_sub(s.units.len() as u64){let legacy_index=(u64::MAX-endpoint.constituent_id.0)as usize;if let Some(id)=s.units.get(legacy_index).map(|u|u.physical_id){endpoint.constituent_id=id}else{return Err(serde::de::Error::custom("bond references missing legacy unit"))}}}if !s.units.iter().any(|u|u.physical_id==bond.endpoint_a.constituent_id)||!s.units.iter().any(|u|u.physical_id==bond.endpoint_b.constituent_id){return Err(serde::de::Error::custom("bond references missing physical constituent"))}}Ok(Self{units:s.units,bonds:s.bonds,next_constituent_id:next})}}
impl PhysicalConstituentGraph{pub fn new()->Self{Self{units:Vec::new(),bonds:Vec::new(),next_constituent_id:1}}pub(crate)fn push_bond_unchecked(&mut self,b:Bond)->usize{self.bonds.push(b);self.bonds.len()-1}pub fn add_unit(&mut self,mut u:StructuralUnit)->usize{let index=self.units.len();let id=PhysicalConstituentId(self.next_constituent_id);self.next_constituent_id=self.next_constituent_id.saturating_add(1);u.physical_id=id;self.units.push(u);index}pub fn physical_id(&self,unit_index:usize)->Option<PhysicalConstituentId>{self.units.get(unit_index).map(|u|u.physical_id)}pub fn unit_index(&self,id:PhysicalConstituentId)->Option<usize>{self.units.iter().position(|u|u.physical_id==id)}pub fn physical_constituent_ids(&self)->Vec<PhysicalConstituentId>{self.units.iter().map(|u|u.physical_id).collect()}fn endpoint_index(&self,e:BondEndpoint)->Option<usize>{self.unit_index(e.constituent_id)}pub fn is_valid_bond(&self,b:&Bond,c:&[BaseResource])->bool{let Some(a)=self.endpoint_index(b.endpoint_a)else{return false};let Some(d)=self.endpoint_index(b.endpoint_b)else{return false};if !b.is_valid(|e|self.endpoint_index(e).and_then(|i|e.location.world_point(self.units.get(i)?,c)).is_some()){return false}if units_strictly_overlap(&self.units[a],&self.units[d],c){return false}let Some(pa)=self.units[a].properties(c)else{return false};let Some(pb)=self.units[d].properties(c)else{return false};let strength=crate::combine::bond_strength(pa,pb);strength.is_finite()&&(0.0..=1.0).contains(&strength)}pub fn connection_site(&self,s:ConnectionSiteRef,c:&[BaseResource])->Option<ConnectionPoint>{match self.units.get(s.unit_index)?.connection_sites(c)?{ConnectionSites::Corners(p)=>p.get(s.point_index).copied(),ConnectionSites::Endpoints(p)=>p.get(s.point_index).copied(),_=>None}}pub fn available_connection_sites(&self,c:&[BaseResource])->Vec<ConnectionSiteRef>{let mut out=Vec::new();for i in 0..self.units.len(){match self.units[i].connection_sites(c){Some(ConnectionSites::Corners(points))|Some(ConnectionSites::Endpoints(points))=>for j in 0..points.len(){out.push(ConnectionSiteRef{unit_index:i,point_index:j})},_=>{}}}out}pub fn connected_components(&self)->Vec<Vec<usize>>{let mut adjacency=vec![Vec::<usize>::new();self.units.len()];for b in &self.bonds{let(Some(a),Some(d))=(self.unit_index(b.endpoint_a.constituent_id),self.unit_index(b.endpoint_b.constituent_id))else{continue};adjacency[a].push(d);adjacency[d].push(a)}let mut visited=vec![false;self.units.len()];let mut out=Vec::new();for start in 0..self.units.len(){if visited[start]{continue}let mut stack=vec![start];visited[start]=true;let mut component=Vec::new();while let Some(u)=stack.pop(){component.push(u);for &next in &adjacency[u]{if !visited[next]{visited[next]=true;stack.push(next)}}}component.sort_unstable();out.push(component)}out}pub fn component_connection_sites(&self,component:&[usize],catalog:&[BaseResource])->Vec<ConnectionSiteRef>{let set:HashSet<usize>=component.iter().copied().collect();self.available_connection_sites(catalog).into_iter().filter(|s|set.contains(&s.unit_index)).collect()}pub fn connection_load(&self,u:usize,location:ConnectionEndpoint,_c:&[BaseResource])->f64{let Some(id)=self.physical_id(u)else{return 0.0};self.bonds.iter().filter(|b|b.touches(id,location)).map(|b|crate::combine::experimental_bond_strength(b.bond_energy)).sum()}pub fn connection_count(&self,u:usize,location:ConnectionEndpoint)->usize{let Some(id)=self.physical_id(u)else{return 0};self.bonds.iter().filter(|b|b.touches(id,location)).count()}pub fn break_bond(&mut self,i:usize)->Option<Bond>{if i<self.bonds.len(){Some(self.bonds.remove(i))}else{None}}pub fn break_matching_bond(&mut self,t:Bond)->Option<Bond>{let i=self.bonds.iter().position(|b|b.has_same_identity(t))?;self.break_bond(i)}pub fn disconnect_point(&mut self,u:usize,location:ConnectionEndpoint)->Vec<Bond>{let Some(id)=self.physical_id(u)else{return Vec::new()};let mut out=Vec::new();let mut i=0;while i<self.bonds.len(){if self.bonds[i].touches(id,location){out.push(self.bonds.remove(i))}else{i+=1}}out}pub fn loaded_points(&self)->Vec<(usize,ConnectionEndpoint)>{let mut out:Vec<(usize,ConnectionEndpoint)>=Vec::new();for b in &self.bonds{for e in[b.endpoint_a,b.endpoint_b]{if let Some(u)=self.unit_index(e.constituent_id){if !out.iter().any(|(i,p):&(usize,ConnectionEndpoint)|*i==u&&p.same_location(e.location)){out.push((u,e.location))}}}}out}}
pub type OrganismStructure=PhysicalConstituentGraph;
pub fn formation_threshold(a:f64,b:f64,la:f64,lb:f64)->f64{let la=la.max(0.0);let lb=lb.max(0.0);((a+b)/2.0)*(1.0+la.sqrt()+lb.sqrt())}
#[cfg(test)]mod tests{use super::*;#[test]fn physical_constituents_receive_stable_ids(){let mut s=OrganismStructure::new();let a=s.add_unit(StructuralUnit::new("Carbon",Placement{x:0.0,y:0.0,rotation_radians:0.0}));let b=s.add_unit(StructuralUnit::new("Hydrogen",Placement{x:1.0,y:0.0,rotation_radians:0.0}));assert_ne!(s.physical_id(a),s.physical_id(b));}#[test]fn bond_identity_uses_physical_ids(){let a=PhysicalConstituentId(11);let b=PhysicalConstituentId(22);let x=Bond{endpoint_a:BondEndpoint::new(a,ConnectionEndpoint::Corner{point_index:0}),endpoint_b:BondEndpoint::new(b,ConnectionEndpoint::Corner{point_index:1}),strength:0.5,bond_energy:1.0};let y=Bond{endpoint_a:BondEndpoint::new(a,ConnectionEndpoint::Corner{point_index:0}),endpoint_b:BondEndpoint::new(b,ConnectionEndpoint::Corner{point_index:1}),strength:0.5,bond_energy:1.0};assert!(x.has_same_identity(&y));}#[test]fn structural_unit_serialization_uses_material_directly(){let unit=StructuralUnit::new("Carbon",Placement{x:0.0,y:0.0,rotation_radians:0.0});let encoded=serde_json::to_string(&unit).unwrap();assert!(encoded.contains("\"material\":{\"parts\""));let decoded:StructuralUnit=serde_json::from_str(&encoded).unwrap();assert_eq!(decoded.material,unit.material);}#[test]fn legacy_structural_material_wrapper_deserializes(){let encoded=r#"{"physical_id":0,"material":{"material":{"parts":[["Carbon",1.0]],"internal_bonds":[]}},"placement":{"x":0.0,"y":0.0,"rotation_radians":0.0}}"#;let decoded:StructuralUnit=serde_json::from_str(encoded).unwrap();assert_eq!(decoded.material,Material::free_base("Carbon",1.0));assert!(decoded.geometry.is_none());}#[test]fn composite_material_is_accepted_as_structural_material(){let material=Material{parts:vec![("Carbon".into(),2.0),("Hydrogen".into(),3.0)],internal_bonds:vec![]};let unit=StructuralUnit::from_material(material.clone(),Placement{x:0.0,y:0.0,rotation_radians:0.0}).unwrap();assert_eq!(unit.material,material);}}
